using StackExchange.Redis;

var options = new ConfigurationOptions
{
    EndPoints = { { "localhost", 6379 } },
    // Pool settings
    PoolSize = 10,
    ConnectTimeout = 5000,
    KeepAlive = 180,
    // Retry on transient failures
    AbortOnConnectFail = false,
    SyncTimeout = 5000
};

// ConnectionMultiplexer is itself a connection pool
ConnectionMultiplexer mux = ConnectionMultiplexer.Connect(options);
IDatabase db = mux.GetDatabase();

// Dispose when the app shuts down
await mux.DisposeAsync();

const Redis = require('ioredis');

// Create a shared pool
const redis = new Redis({
  host: 'localhost',
  port: 6379,
  // Connection pool settings
  maxRetriesPerRequest: 3,
  retryStrategy: (times) => {
    const delay = Math.min(times * 50, 2000);
    return delay;
  },
  // Keep-alive helps detect dead connections
  keepAlive: true,
  keepAliveTimeout: 60000
});

// ioredis manages a pool per instance
redis.set('pool:status', 'healthy');

async function shutdown() {
  await redis.quit();
  console.log('Redis pool closed');
}
process.on('SIGINT', shutdown);
